size_t current_usage = usage_.load(std::memory_order_relaxed);
while (current_usage > target_usage) {
    // In a real implementation, this would traverse the LRU list and evict entries
    // For this simplified no-op version, we just simulate the behavior
    LRUHandle* old = lru_.next;
    if (old != &lru_) {
        // Remove from LRU list
        old->next->prev = old->prev;
        old->prev->next = old->next;

        // Update usage
        current_usage -= old->charge;
        usage_.store(current_usage, std::memory_order_relaxed);

        // In a real cache, we would delete the handle here
        // delete old;
    } else {
        break; // No more entries to evict
    }
}
